// QCDS Security Lab Work. Created by Patrik Sundblom.
// OpenAI / ChatGPT: research & development support.
import {VERSION,CONDITION_DEFS,LENSES,newProject,validateProject,fingerprint} from './core/engine.mjs';
import {normalizeResearch} from './core/logical-space.mjs';
import {createEagleScene} from './eagle.js';
import {EXAMPLES,loadExample,exampleFor,examplesView,guideView,resultsView,advancedView,stopExplanation} from './guided-work.js';
import {CONDITION_LABELS,ROUTE_LABELS,SCENARIO_LABELS,STATUS_LABELS,ORACLE_LABELS,esc,fmt,pct,tag,routeName,reportMarkup} from './work-data.js';
const $=q=>document.querySelector(q), KEY='qcds-security-lab-work.workspace.v1';
const uid=()=>crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
const scene=createEagleScene($('#eagle-stage'));
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
let motionPaused=reduce.matches;
scene.pause(motionPaused);
$('.motion-btn').setAttribute('aria-pressed',String(motionPaused));$('.motion-btn').setAttribute('aria-label',motionPaused?'Starta animation':'Pausa animation');$('.motion-btn').textContent=motionPaused?'▷':'Ⅱ';
let cases=[],currentId,model=null,view='examples',selectedRoute='',selectedVector='',dimRun=null,quantum=null,jobNumber=0,revision=0,busy=false,saveBlocked=false;
let step=1;
let research=normalizeResearch(),routeQuery='',routeLens='',toastTimer,draft=null,dimensionRequest=0;
const navItems=[['examples','Start & exempel','<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'],['guide','Undersökning','<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="7" cy="5" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="17" cy="19" r="2"/>'],['overview','Resultat','<path d="M4 20V9m8 11V3m8 17v-7"/>'],['advanced','Fördjupning','<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 0v20M3 7l9 5 9-5"/>']];
const current=()=>cases.find(c=>c.id===currentId);
const project=()=>current().project;
function starter(scenario){if(EXAMPLES[scenario])return loadExample(scenario);const p=newProject('custom');p.input.name='Mitt system';return p;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300)}
try {const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(data.schema!=='qcds-security-lab-work/workspace-v1'||!Array.isArray(data.cases)||data.cases.length>100)throw Error('Ogiltig arbetsplats');cases=data.cases.map(c=>({id:typeof c.id==='string'?c.id:uid(),project:validateProject(c.project)}));currentId=cases.some(c=>c.id===data.currentId)?data.currentId:cases[0]?.id;}}catch(e){saveBlocked=true;setTimeout(()=>toast('Tidigare lagring kunde inte läsas. Den bevaras. Exportera ditt nya arbete som JSON.'),800)}
if(!cases.length){currentId=uid();cases=[{id:currentId,project:starter('portal')}];}
research=normalizeResearch(project().research||{});
function save(){project().updatedAt=new Date().toISOString();if(saveBlocked){$('#save-status').textContent='Exportera för att spara';return}try{localStorage.setItem(KEY,JSON.stringify({schema:'qcds-security-lab-work/workspace-v1',cases,currentId}));$('#save-status').textContent='Sparat på enheten'}catch(e){$('#save-status').textContent='Kunde inte spara';toast('Enheten kunde inte spara. Exportera projektet som JSON.')}}
const worker=new Worker(new URL('./engine-worker.js',import.meta.url),{type:'module'}),pending=new Map();
worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;if(data.phase!==undefined){const line=$('#run-status');if(line)line.textContent=['Villkor läses…','Orakel prövas…','Inferens sammanställs…','Belägg binds till aktuellt scope…'][data.phase];return}pending.delete(data.id);clearTimeout(p.timeout);data.error?p.reject(Error(data.error)):p.resolve(data.result)};
worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timeout);p.reject(Error('Beräkningsmotorn kunde inte laddas. Ladda om sidan.'))}pending.clear()};
function calculate(type,args){return new Promise((resolve,reject)=>{const id=++jobNumber;const timeout=setTimeout(()=>{pending.delete(id);reject(Error('Beräkningen tog för lång tid. Minska antalet dimensioner och prova igen.'))},45000);pending.set(id,{resolve,reject,timeout});worker.postMessage({id,type,...args})})}
async function analyzeCurrent(notify=false){const rev=++revision,id=currentId;busy=true;dimRun=null;quantum=null;refreshNav();render();try{const result=await calculate('analyze',{project:project()});if(rev!==revision||id!==currentId)return;model=result;busy=false;selectedRoute=model.routes.some(r=>r.id===selectedRoute)?selectedRoute:model.routes.find(r=>r.id===exampleFor(project())?.focus)?.id||model.routes[0]?.id||'';save();render();if(notify)toast('Analysen är uppdaterad från dina aktuella villkor.')}catch(e){if(rev!==revision)return;busy=false;model=null;renderError(e.message)}}
function refreshNav(){const active=['system','logic','diagnostics'].includes(view)?'advanced':['routes','evidence'].includes(view)?'guide':view;$('#nav').innerHTML=navItems.map(([id,label,icon])=>`<button class="nav-link ${active===id?'active':''}" data-view="${id}" ${active===id?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icon}</svg><span class="nav-label">${label}</span><span class="nav-short">${({examples:'Exempel',guide:'Undersök',overview:'Resultat',advanced:'Fördjupa'})[id]}</span></button>`).join('');$('#breadcrumb').textContent=({system:'System & villkor',logic:'Logiskt rum',diagnostics:'Analysdata',evidence:'Åtgärder'})[view]||navItems.find(n=>n[0]===active)?.[1]||'Undersökning';$('#case-select').innerHTML=cases.map(c=>`<option value="${esc(c.id)}" ${c.id===currentId?'selected':''}>${esc(c.project.input.name)}</option>`).join('');$('#engine-version').textContent=VERSION;}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="page-kicker">${project().example?'EXEMPELSYSTEM':'EGEN UNDERSÖKNING'} <span style="color:#3e617c">/</span> QCDS WORK</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function exampleNote(){return project().example?`<div class="example-note">${tag('EXEMPEL')}<span><strong>Ett färdigt system att utforska.</strong> Genomarbetat fall med tydligt märkta syntetiska observationer.</span><button class="text-btn" data-view="examples">Välj exempel →</button></div>`:''}
function metric(label,value,note,color=''){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value ${color}">${value}</div><div class="metric-note">${note}</div></div>`}
function technicalOverview(){const s=model.searchSpace;return heading('Din säkerhetsbild.','Från systemets villkor till vägar som går att pröva.',`<button class="primary" data-action="analyze">Kör analys <span>↗</span></button>`)+exampleNote()+`<div class="metrics">${metric('Modellerade kandidater',fmt(s.generatedAttackVectors),'Genererade från systemets scope')}${metric('Aktiva kandidater',fmt(s.activeAttackVectors),'Uppfyller de angivna villkoren','cyan')}${metric('Okända villkor',s.unknownMaskDimensions,`${s.maskedLogicalSpace} möjliga tillstånd`,'amber')}${metric('Rapporterade belägg',project().evidence.filter(e=>e.fingerprint===model.fingerprint).length,'Bundna till denna systembeskrivning')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Det logiska rummet</h2><p>Varje punkt är en genererad kandidat.</p></div><button class="text-btn" data-view="logic">Utforska ↗</button></div>${vectorMap()}<div class="legend"><span><i></i>Aktiv ${fmt(s.activeAttackVectors)}</span><span><i class="conditional"></i>Villkorad ${fmt(s.conditionalAttackVectors)}</span><span><i class="rejected"></i>Utesluten ${fmt(s.rejectedAttackVectors)}</span></div></section><section class="panel"><div class="panel-header"><div><h2>Orakelöversikt</h2><p>Vad behöver prövas härnäst?</p></div><span style="color:#50758f">◈</span></div><div class="oracle-list">${model.oracles.map((o,i)=>`<div class="oracle-row"><span class="oracle-symbol">0${i+1}</span><div><strong>${ORACLE_LABELS[o.name]}</strong><p>${['Ingångar och tillitsgränser','Aktör, resurs och åtgärd','Kontroll och möjlig omväg','Observationer med källa'][i]}</p></div>${tag(ORACLE_LABELS[o.state]||o.state,/GAP|CONFLICT|AWAITING/.test(o.state)?'amber':'muted')}</div>`).join('')}</div><div class="panel-body"><p class="disclaimer">Aktiv kandidat betyder möjlig enligt modellen. Belägg behövs för att stödja eller motsäga vägen.</p></div></section></div><div class="phase-strip">${[['Villkorsbildning',`${s.knownMaskDimensions} kända · ${s.unknownMaskDimensions} okända`],['Orakel & begränsning',`${s.rejectedAttackVectors} kandidater uteslutna`],['Rekursiv inferens',`${s.survivingRoutes} vägar med kontrollfrågor`],['Sanningsprövning','Belägg binds till aktuellt scope']].map(([t,d],i)=>`<div class="phase ${i===3?'last':''}"><b>0${i+1}</b><strong>${t}</strong><p>${d}</p></div>`).join('')}</div><div class="section-title"><h2>Vägar att undersöka</h2><button class="text-btn" data-view="routes">Alla ${model.routes.length} vägar →</button></div>${routeRows(model.routes.slice(0,4))}`}
function vectorMap(){const vectors=model.attackVectorSpace.vectors,counters={};const groups=8,cx=325,cy=148;const dots=vectors.map((v,i)=>{const group=Math.max(0,Number(v.routeFamily?.slice(1)||1)-1),within=counters[v.routeFamily]||0;counters[v.routeFamily]=within+1;const a=group/groups*Math.PI*2-Math.PI/2;const gx=cx+Math.cos(a)*183,gy=cy+Math.sin(a)*83;const angle=within*2.399963,r=Math.sqrt(within)*4.2;const x=gx+Math.cos(angle)*r,y=gy+Math.sin(angle)*r*.72;return `<circle class="vector-dot" aria-hidden="true" tabindex="-1" data-vector="${esc(v.id)}" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="1.75" fill="${v.state==='ACTIVE'?'#66d8eb':v.state==='CONDITIONAL'?'#ddba75':'#2c455d'}"><title>${esc(v.id+' · '+v.title+' · '+v.state)}</title></circle>`}).join('');let lines='';for(let i=0;i<8;i++){const a=i/8*Math.PI*2-Math.PI/2;lines+=`<path d="M${cx} ${cy}Q${cx+Math.cos(a-.35)*90} ${cy+Math.sin(a-.35)*50} ${cx+Math.cos(a)*183} ${cy+Math.sin(a)*83}" fill="none" stroke="#254862" opacity=".6"/>`}
return `<svg class="inference-map" viewBox="0 0 650 300" role="img" aria-label="Kandidater i åtta grupper. Aktiv, villkorad och utesluten status hämtas från den aktuella analysen."><ellipse cx="325" cy="148" rx="244" ry="110" fill="none" stroke="#254059" stroke-dasharray="2 9"/><ellipse cx="325" cy="148" rx="122" ry="64" fill="none" stroke="#18344c"/>${lines}${dots}<circle cx="325" cy="148" r="35" fill="#10263b" stroke="#41738d"/><path d="m325 130 15 8v18l-15 8-15-8v-18Z" fill="none" stroke="#6ce7f5" opacity=".6"/><text x="325" y="152" class="map-center">Q</text><text x="22" y="26" class="map-label">${fmt(vectors.length)} CANDIDATES</text><text x="490" y="281" class="map-label">CONDITION SPACE</text></svg>`}
function routeRows(routes){return routes.length?`<div class="route-list">${routes.map(r=>`<button class="route-row" data-route="${r.id}"><span class="route-id">${r.id}</span><div><h3>${esc(routeName(r))}</h3><p>${r.attackVectorCount} kandidater · ${esc(r.hitLenses.join(' / '))}</p></div>${tag(r.conditional?'Villkorad':r.records?.length?'Belägg finns':'Hypotes',r.conditional?'amber':'muted')}<span class="arrow">↗</span></button>`).join('')}</div>`:`<div class="empty-state"><h2>Inga vägar i detta urval</h2><p>Ändra filtret eller granska systemets villkor och perspektiv. Ett tomt urval är inte en säkerhetscertifiering.</p></div>`}
function systemView(){if(!draft)draft=structuredClone(project());const p=draft;return heading('Beskriv systemet.','Markera det du vet. Låt resten vara okänt.')+`<form id="system-form"><div class="panel form-panel"><h2>Vad ska skyddas?</h2><div class="field-grid"><div class="field"><label for="system-name">Systemets namn</label><input id="system-name" name="name" value="${esc(p.input.name)}" maxlength="160" required></div><div class="field"><label for="system-assets">Skyddsvärden, separerade med komma</label><input id="system-assets" name="assets" value="${esc(p.input.assets.join(', '))}" maxlength="3000" placeholder="Kunddata, inloggning, betalningar"></div><div class="field full"><label for="system-description">Hur fungerar systemet?</label><textarea id="system-description" name="description" maxlength="20000" required placeholder="Vem använder systemet? Vilka uppgifter behandlas? Vilka tjänster kan det anropa?">${esc(p.input.description)}</textarea></div><div class="field full"><label for="system-goal">Vilket oönskat utfall undersöker vi?</label><textarea id="system-goal" name="attackerGoal" maxlength="20000" required placeholder="Exempel: En användare får åtkomst till en annan användares uppgifter.">${esc(p.input.attackerGoal)}</textarea><p class="help">Texten beskriver scope. Kandidaterna styrs av de uttryckliga villkoren nedan.</p></div></div></div><div class="section-title"><h2>Systemets villkor</h2><span class="help">1 = ja · 0 = nej · ? = okänt</span></div><div class="panel form-panel"><div class="condition-list">${CONDITION_DEFS.map(([key],i)=>`<div class="condition-row"><label id="label-${key}">${CONDITION_LABELS[key]}<small>C${i+1} / ${key}</small></label><div class="tri-state" role="group" aria-labelledby="label-${key}">${[['1','Ja',true],['0','Nej',false],['?','Okänt',null]].map(([symbol,label,val])=>`<button type="button" data-condition="${key}" data-value="${symbol}" class="${val===p.input.flags[key]?'active':''} ${symbol==='?'?'unknown':''}" aria-pressed="${val===p.input.flags[key]}" aria-label="${label}">${symbol}</button>`).join('')}</div></div>`).join('')}</div><p class="disclaimer">Kända 1/0 låses. Bara okända villkor förgrenas. Ett angivet skydd räknas inte som bevis för att det fungerar.</p></div><div class="section-title"><h2>Perspektiv</h2><span class="help">Samma kandidater, flera synvinklar</span></div><div class="lens-grid">${Object.keys(LENSES).map(name=>`<button type="button" class="lens-toggle ${p.excludedLenses.includes(name)?'':'active'}" data-lens="${esc(name)}" aria-pressed="${!p.excludedLenses.includes(name)}">${p.excludedLenses.includes(name)?'○':'✓'} ${esc(name)}</button>`).join('')}</div><div class="form-actions"><button class="primary" type="submit">Spara & fortsätt till vägar <span>→</span></button></div></form>`}
function routesView(){let list=model.routes.filter(r=>(!routeQuery||JSON.stringify(r).toLowerCase().includes(routeQuery.toLowerCase())||routeName(r).toLowerCase().includes(routeQuery.toLowerCase()))&&(!routeLens||r.hitLenses.includes(routeLens)));return heading('Följ vägen. Pröva skyddet.','Öppna en väg för att se villkor, skydd, möjliga omvägar och test.')+`<div class="filter-bar"><input id="route-search" aria-label="Sök angreppsvägar" placeholder="Sök väg, mekanism eller skydd…" value="${esc(routeQuery)}"><select id="route-lens" aria-label="Filtrera perspektiv"><option value="">Alla perspektiv</option>${Object.keys(LENSES).map(l=>`<option ${routeLens===l?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div id="route-results">${routeRows(list)}</div><div class="section-title"><h2>Ramverkens täckning</h2><span class="help">Kategorier kan överlappa</span></div><div class="table-wrap"><table><thead><tr><th>Perspektiv</th><th>Aktiva</th><th>Villkorade</th><th>Uteslutna</th></tr></thead><tbody>${model.lenses.filter(l=>l.active).map(l=>{const vs=model.attackVectorSpace.vectors.filter(v=>v.frameworks.some(f=>f.lens===l.name));return `<tr><td>${esc(l.name)}</td>${['ACTIVE','CONDITIONAL','REJECTED'].map(st=>`<td class="number">${fmt(vs.filter(v=>v.state===st).length)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`}
function openRoute(id){const r=model.routes.find(r=>r.id===id);if(!r)return;selectedRoute=id;const recursive=model.recursive.find(x=>x.id===id);showModal(`<div class="modal-head"><span class="eyebrow">ANGREPPSVÄG / ${r.id}</span><button class="icon-btn" data-action="close" aria-label="Stäng">×</button></div><h2 class="detail-title">${esc(routeName(r))}</h2><div class="detail-meta">${tag(STATUS_LABELS[r.status]||r.status,r.conditional?'amber':'')}${tag(r.attackVectorCount+' kandidater','muted')}</div><div class="scope-path">${esc(r.path)}</div>${[['Varför finns vägen?',r.why],['Vad ska stoppa den?',r.control],['Hur skulle skyddet kunna kringgås?',r.bypass],['Vad kan stödja eller motsäga vägen?',r.verify]].map(([t,d],i)=>`<div class="info-block ${i===3?'gold':''}"><h3>0${i+1} · ${t}</h3><p>${esc(d)}</p></div>`).join('')}${r.missing.length?`<p class="disclaimer">Okända förutsättningar: ${r.missing.map(k=>esc(CONDITION_LABELS[k]||k)).join(', ')}</p>`:''}${recursive?`<details><summary>Visa den rekursiva kontrollkedjan</summary>${recursive.stages.map(s=>`<div class="info-block"><h3>${esc(s.type)}</h3><p>${esc(s.text)}</p></div>`).join('')}</details>`:''}<details><summary>${r.attackVectorCount} kandidater · visa motorns exempel</summary>${r.attackVectors.slice(0,10).map(v=>`<button class="route-row" data-vector="${esc(v.id)}"><span class="route-id">${esc(v.id)}</span><div><h3>${esc(v.title)}</h3><p>${esc(v.variantLabel)} · ${esc(v.targetLabel)}</p></div><span class="arrow">↗</span></button>`).join('')}</details><div class="form-actions"><button class="primary" data-action="route-evidence">Lägg till belägg <span>→</span></button></div>`)}
function openVector(id){const v=model.attackVectorSpace.vectors.find(v=>v.id===id);if(!v)return;selectedVector=id;showModal(`<div class="modal-head"><span class="eyebrow">KANDIDAT / ${esc(id)}</span><button class="icon-btn" data-action="close" aria-label="Stäng">×</button></div><h2 class="detail-title">${esc(v.title)}</h2><div class="detail-meta">${tag(STATUS_LABELS[v.state],v.state==='CONDITIONAL'?'amber':'')}${tag(v.variantLabel,'muted')}</div><div class="scope-path">${esc(v.path)}</div><div class="info-block"><h3>Mekanism</h3><p>${esc(v.mechanism)}</p></div><div class="info-block"><h3>Skydd</h3><p>${esc(v.control)}</p></div><div class="info-block gold"><h3>Test</h3><p>${esc(v.verify)}</p></div>${v.rejectedReason?`<p class="disclaimer">${esc(v.rejectedReason)}</p>`:''}<div class="form-actions"><button class="primary" data-action="focus-vector">Öppna i logiskt rum →</button></div>`)}
function logicView(){const vectors=model.attackVectorSpace.vectors.filter(v=>v.frameworks.length);if(!research.focus)research.focus=vectors.find(v=>v.state!=='REJECTED')?.id||vectors[0]?.id||'';return heading('Det logiska rummet.','Fördjupning: ändra ett villkor och följ utfallet. Grover stannar automatiskt; 40 är bara taket.')+`<section class="panel form-panel"><div class="logic-top"><div class="field"><label for="focus-vector">Kandidat att pröva</label><select id="focus-vector">${vectors.map(v=>`<option value="${esc(v.id)}" ${v.id===research.focus?'selected':''}>${esc(v.id+' · '+v.title+' / '+v.variantLabel+' / '+v.targetLabel)}</option>`).join('')}</select></div><div class="field"><label for="run-mode">Flöde</label><select id="run-mode">${[['hybrid','Hybrid'],['parallel','Parallellt'],['sequential','Sekventiellt']].map(([v,l])=>`<option value="${v}" ${research.mode===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="iterations">Iterationstak</label><input id="iterations" type="number" min="0" max="40" step="1" value="${research.maxIterations}"></div></div><details ${research.walk.length?'open':''}><summary>Vad händer om ett villkor ändras?</summary><div class="walk-fields"><select id="walk-key" aria-label="Dimension att ändra">${[...CONDITION_DEFS.map(([k])=>({key:k,label:CONDITION_LABELS[k]})),...research.dimensions].map(d=>`<option value="${d.key}">${esc(d.label)}</option>`).join('')}</select><select id="walk-value" aria-label="Nytt dimensionsvärde"><option value="?">? Okänt</option><option value="1">1 Ja</option><option value="0">0 Nej</option><option value="ABSENT">Ta bort dimension</option></select><button class="secondary" data-action="add-walk">Lägg till</button></div><div class="walk-list">${research.walk.map((w,i)=>`<span class="walk-chip">${esc(CONDITION_LABELS[w.key]||w.key)} = ${esc(w.value)}<button data-remove-walk="${i}" aria-label="Ta bort ändring">×</button></span>`).join('')}</div><p class="help">Detta är ett utforskningsscenario. Systemets grundvillkor ändras först i vyn System & villkor.</p></details><details><summary>Eget kontrollorakel${research.controls.length?' · '+research.controls.length+' definierade':''}</summary><p class="help">Lägg till ett skydd för den valda kandidaten. 1 betyder att skyddet fungerar inom det angivna scopet, 0 att det fallerar, ? att det är oprövat. Modellen kräver att skyddet fallerar för att vägen ska överleva.</p><div class="field" style="margin-top:16px"><label for="control-label">Vilket skydd ska prövas?</label><input id="control-label" maxlength="240" placeholder="Resurskontrollen stoppar åtkomst mellan konton"></div><div class="field"><label for="control-test">Test eller motfråga</label><input id="control-test" maxlength="3000" placeholder="Pröva samma resurs via en alternativ ingång"></div><div class="field"><label for="control-value">Skyddets status</label><select id="control-value"><option value="?">? Oprövat</option><option value="1">1 Fungerar enligt angivet underlag</option><option value="0">0 Fallerar enligt angivet underlag</option></select></div><button class="secondary" data-action="add-control">Lägg till kontrollorakel</button>${research.controls.length?`<div class="walk-list">${research.controls.map((c,i)=>`<span class="walk-chip">${esc(c.vectorId)} · ${esc(c.label)}<button data-remove-control="${i}" aria-label="Ta bort kontrollorakel">×</button></span>`).join('')}</div>`:''}</details><div class="form-actions"><button class="secondary" data-action="unknown-demo">Pröva okända villkor</button><button class="primary" data-action="run-dimensions">Kör inferens <span>→</span></button></div></section><div id="dimension-result">${dimRun?dimensionResult():`<div class="empty-state" style="margin-top:22px"><h2>Följ en verklig beräkning.</h2><p>Välj en kandidat och kör inferens. Du får exakta maskantal, dimensionspåverkan och Grover-kurvan för det valda oraklet.</p><span class="help">CPU-simulering · ideal Grover · automatiskt stopp · tak 40</span></div>`}</div>`}
function traceChart(amp){const W=600,H=210,left=44,top=17,width=535,height=150;const count=Math.max(1,amp.trace.length-1);const points=amp.trace.map(t=>`${left+t.iteration/count*width},${top+(1-t.probability)*height}`).join(' ');const x=left+amp.iterations/count*width,y=top+(1-amp.probability)*height;return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Oraklets sannolikhetsmassa per Grover-iteration. Vald iteration ${amp.iterations}, massa ${pct(amp.probability)}.">${[0,.5,1].map(p=>`<path class="chart-grid" d="M44 ${top+(1-p)*height}h535"/><text x="5" y="${top+(1-p)*height+3}">${p*100}%</text>`).join('')}<path d="M44 ${top+.05*height}h535" stroke="#c4a26a" stroke-dasharray="3 5" opacity=".55"/><polyline class="chart-line" points="${points}"/><path d="M${x} ${top}v150" stroke="#e8bb74" opacity=".4"/><circle cx="${x}" cy="${y}" r="5" fill="#e8bb74" stroke="#f8e7c2"/><text x="44" y="194">0</text><text x="555" y="194">${amp.trace.at(-1)?.iteration??0}</text><text x="235" y="199">Grover-iteration</text></svg>`}
function dimensionResult(){const r=dimRun,a=r.final.amplification;return `<div class="section-title"><h2>Resultat · ${esc(r.focus.id)}</h2>${tag('EXAKT MASKRÄKNING')}</div><div class="logic-metrics"><div class="mini-metric"><strong>${esc(r.final.markedStates)} / ${esc(r.final.totalStates)}</strong><p>Accepterade tillstånd</p></div><div class="mini-metric"><strong>${pct(a.probability)}</strong><p>Massa vid vald iteration</p></div><div class="mini-metric"><strong>${a.iterations} steg</strong><p>Valt resultat · tak ${a.iterationBudget}</p></div></div><div class="two-column"><section class="panel"><div class="panel-header"><div><h2>Förstärkning genom Grover</h2><p>Guld visar resultatet som behålls. Kurvan slutar vid automatiskt stopp.</p></div></div><div class="panel-body">${traceChart(a)}<div class="distribution"><span style="width:${Math.max(0,Math.min(100,a.probability*100))}%"></span></div><p class="help">${esc(stopExplanation(a))}</p><details><summary>Varför stannar Grover?</summary><p class="help">Sökningen stannar vid 95 %, eller efter tre steg utan en förbättring på mer än 0,1 % relativt det tidigare bästa värdet. Bästa prövade resultat behålls. Senare toppar kan hoppas över för att spara arbete. Grovers sannolikheter kan oscillera; stoppet betyder inte att en kvantkrets har konvergerat.</p></details><p class="disclaimer">Orakelpassning är inte verifiering av en sårbarhet. Detta är en ideal CPU-simulering av Grover med exakt klassisk maskräkning.</p></div></section><section class="panel"><div class="panel-header"><h2>Koherens & avgränsning</h2></div><div class="panel-body"><div class="info-block"><h3>Orienteringskontroll</h3><p>${r.rotations.filter(x=>x.agrees).length} av ${r.rotations.length} rotationer behåller samma antal accepterade tillstånd.</p></div><div class="info-block"><h3>Dimensionsuteslutning</h3><p>${r.lanes.length} separata körningar. ${r.binding.laneAgreement} behåller fokuskandidatens status.</p></div><div class="info-block gold"><h3>Beläggsbindning</h3><p>${esc(STATUS_LABELS[r.binding.status]||r.binding.status)}. Observationer måste kopplas till just denna kandidat och dess villkor.</p></div><button class="secondary" data-action="quantum">Jämför ideal & brusig krets →</button></div></section></div>${r.lanes.length?`<details><summary>Visa dimensionspåverkan · ${r.lanes.length} körningar</summary><div class="table-wrap"><table><thead><tr><th>Utesluten dimension</th><th>Ändrade kandidater</th><th>Accepterade</th></tr></thead><tbody>${r.lanes.map(l=>`<tr><td>${esc(CONDITION_LABELS[l.excluded]||l.label)}</td><td>${l.affected.length}</td><td>${esc(l.markedStates)} / ${esc(l.totalStates)}</td></tr>`).join('')}</tbody></table></div></details>`:''}${r.sequential.length?`<details><summary>Sekventiella steg</summary><div class="table-wrap"><table><thead><tr><th>Steg</th><th>Dimension</th><th>Värde</th><th>Accepterade</th></tr></thead><tbody>${r.sequential.map(s=>`<tr><td>${s.step}</td><td>${esc(CONDITION_LABELS[s.key]||s.key)}</td><td>${esc(s.value)}</td><td>${esc(s.markedStates)}</td></tr>`).join('')}</tbody></table></div></details>`:''}<div class="form-actions"><button class="secondary" data-action="export-run">Exportera körning</button></div><details><summary>Rapportera observation för just denna körning</summary><form id="dimension-evidence"><div class="field"><label for="d-source">Källa / testreferens</label><input id="d-source" name="source" required maxlength="2000"></div><div class="field"><label for="d-observation">Observation</label><textarea id="d-observation" name="observation" required maxlength="3000"></textarea></div><div class="field"><label for="d-outcome">Utfall</label><select id="d-outcome" name="outcome"><option value="inconclusive">Oavgjort</option><option value="supports">Stödjer vägen</option><option value="refutes">Motsäger vägen</option></select></div><button class="primary" type="submit">Bind belägg till körningen</button><p class="help">${r.binding.records.length} observationer gäller denna körning. ${r.binding.archivedRecords} gäller andra eller äldre scope.</p></form></details><div id="quantum-result">${quantum?quantumResult():''}</div>`}
function quantumResult(){const q=quantum;return `<section class="panel form-panel" style="margin-top:20px"><h2>Ideal krets & brusmodell</h2><div class="logic-metrics"><div class="mini-metric"><strong>${pct(q.ideal.probability)}</strong><p>Ideal tillståndsvektor</p></div><div class="mini-metric"><strong>${q.noisy.status==='completed'?pct(q.noisy.probability):'Begränsad'}</strong><p>Brusig densitetsmatris</p></div><div class="mini-metric"><strong>${q.circuit.qubits}</strong><p>Interagerande qubits</p></div></div><p class="help">${q.circuit.iterations} iterationer · ${q.noise.shots} simulerade mätningar · seed ${q.noise.seed}. Maximalt fel mot klassisk referens: ${q.ideal.maxReferenceError.toExponential(2)}.</p>${q.noisy.reason?`<p class="disclaimer">${esc(q.noisy.reason)}</p>`:''}<details><summary>Brus och reproduktion</summary><p class="help">Lokalt depolariseringsbrus: en qubit ${q.noise.single}, två qubits ${q.noise.two}. Avläsningsfel: ${q.noise.readout}. Modellen är inte kalibrerad mot någon fysisk QPU.</p><div class="form-actions"><button class="secondary" data-action="export-quantum">Exportera jämförelse</button></div></details></section>`}
function evidenceView(){const routes=model.routes;const r=routes.find(x=>x.id===selectedRoute)||routes[0];if(!r)return heading('Belägg & åtgärder.','Koppla observationer till en specifik väg.')+`<div class="empty-state"><h2>Ingen aktiv väg att dokumentera</h2><p>Börja med systemets villkor och kör analysen.</p><button class="primary" data-view="system">Till systemet →</button></div>`;selectedRoute=r.id;const p=project(),records=p.evidence.filter(e=>e.findingId===r.id&&e.fingerprint===model.fingerprint);const savedAction=p.actions[r.id],a=savedAction?.fingerprint===model.fingerprint?savedAction:{owner:'',note:'',status:'open'};return heading('Beläggen avgör.','Dokumentera vad som faktiskt observerats och vem som tar nästa steg.')+`<div class="field"><label for="evidence-route">Angreppsväg</label><select id="evidence-route">${routes.map(x=>`<option value="${x.id}" ${x.id===selectedRoute?'selected':''}>${x.id} · ${esc(routeName(x))}</option>`).join('')}</select></div><div class="two-column"><div class="stack"><section class="panel form-panel"><h2>Lägg till observation</h2><form id="evidence-form"><div class="field"><label for="e-source">Källa eller testreferens</label><input id="e-source" name="source" required maxlength="2000" placeholder="Test-ID, dokument eller loggreferens"></div><div class="field"><label for="e-observation">Vad observerades?</label><textarea id="e-observation" name="observation" required maxlength="10000" placeholder="Beskriv villkor, åtgärd och faktiskt utfall."></textarea></div><div class="field"><label for="e-outcome">Vad säger observationen om vägen?</label><select id="e-outcome" name="outcome"><option value="inconclusive">Oavgjort – mer underlag behövs</option><option value="supports">Stödjer hypotesen</option><option value="refutes">Motsäger hypotesen</option></select></div><div class="form-actions"><button class="primary" type="submit">Spara belägg →</button></div></form><p class="disclaimer">Observationen sparas som rapporterad och binds till den aktuella systembeskrivningen. Ändrat scope gör tidigare belägg historiska.</p></section><section class="panel form-panel"><h2>Nästa åtgärd</h2><form id="action-form"><div class="action-row"><div><label for="a-owner">Ansvarig</label><input id="a-owner" name="owner" maxlength="200" value="${esc(a.owner)}" placeholder="Namn eller roll"></div><div><label for="a-status">Status</label><select id="a-status" name="status">${[['open','Öppen'],['progress','Pågår'],['done','Klar']].map(([v,l])=>`<option value="${v}" ${a.status===v?'selected':''}>${l}</option>`).join('')}</select></div><textarea name="note" aria-label="Åtgärd" maxlength="5000" required placeholder="Vad ska göras?">${esc(a.note)}</textarea></div><div class="form-actions"><button class="secondary" type="submit">Spara åtgärd</button></div></form>${savedAction&&savedAction.fingerprint!==model.fingerprint?'<p class="help">En äldre åtgärd finns i exporten. Bekräfta den för aktuellt scope.</p>':''}</section></div><div><section class="panel form-panel"><h2>Föreslaget test</h2><div class="info-block gold"><p>${esc(r.verify)}</p></div><button class="text-btn" data-route="${r.id}">Visa hela vägen ↗</button></section><div class="section-title"><h2>Aktuella observationer</h2>${tag(records.length+' st','muted')}</div>${records.length?records.map(e=>`<article class="evidence-record">${tag(e.outcome==='supports'?'Stödjer':e.outcome==='refutes'?'Motsäger':'Oavgjort',e.outcome==='inconclusive'?'amber':'')}<p><strong>${esc(e.source)}</strong></p><p>${esc(e.observation)}</p><small>${new Date(e.createdAt).toLocaleString('sv-SE')}</small></article>`).join(''):`<div class="empty-state"><p>Inga observationer för denna väg och detta scope ännu.</p></div>`}${model.archivedEvidence?`<p class="disclaimer">${model.archivedEvidence} observationer hör till äldre scope och finns kvar i projektet.</p>`:''}</div></div>`}
function render(){refreshNav();if(view==='examples'){$('#content').innerHTML=examplesView(project());return}if(busy||!model){$('#content').innerHTML=heading('Sammanställer systemet.','Oraklen utgår från dina aktuella villkor.')+`<div class="loading"><span class="spinner"></span><span id="run-status">Villkor → orakel → inferens → belägg</span></div>`;return}if(view==='guide'&&step===1&&!draft)draft=structuredClone(project());const contents={examples:()=>examplesView(project()),guide:()=>guideView(draft||project(),model,step,selectedRoute),overview:()=>resultsView(project(),model),advanced:advancedView,diagnostics:technicalOverview,system:systemView,routes:routesView,logic:logicView,evidence:evidenceView};$('#content').innerHTML=(contents[view]||contents.guide)();if(['system','logic','evidence','diagnostics'].includes(view))$('#content').insertAdjacentHTML('afterbegin','<button class="text-btn return-to-guide" data-view="guide">← Tillbaka till undersökningen</button>');}
function renderError(message){$('#content').innerHTML=heading('Beräkningen kunde inte slutföras.','Dina indata finns kvar.')+`<div class="empty-state error"><p>${esc(message)}</p><button class="primary" data-action="analyze">Försök igen</button></div>`}
function showModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function newCaseDialog(){showModal(`<div class="modal-head"><h2>Vad vill du undersöka?</h2><button class="icon-btn" data-action="close" aria-label="Stäng">×</button></div><div class="scenario-grid"><button class="scenario-btn own" data-scenario="custom"><strong>＋ Beskriv ett eget system</strong><p>Börja med okända villkor och dina egna skyddsvärden.</p></button>${Object.entries(SCENARIO_LABELS).map(([key,[title,desc]])=>`<button class="scenario-btn" data-scenario="${key}"><strong>${title}</strong><p>${desc}</p></button>`).join('')}</div><p class="modal-help">Varje val skapar en egen undersökning. Genomarbetade exempel innehåller märkta syntetiska observationer. Egna system börjar utan belägg.</p>`)}
function commitDraft(){if(!draft)return;current().project=draft;draft=null;save()}
async function go(next){const changed=!!draft;if(changed)commitDraft();view=next;if(changed)await analyzeCurrent();else render();window.scrollTo({top:0,behavior:reduce.matches?'instant':'smooth'});$('#content').focus({preventScroll:true})}
function enter(){$('#intro').hidden=true;$('#workspace').hidden=false;scene.pause(true);history.replaceState(null,'','#work');render();window.scrollTo(0,0)}
function intro(){$('#workspace').hidden=true;$('#intro').hidden=false;scene.pause(motionPaused);scene.replay();history.replaceState(null,'','#intro');window.scrollTo(0,0)}
function download(filename,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function captureResearch(){research.focus=$('#focus-vector')?.value||research.focus;research.mode=$('#run-mode')?.value||research.mode;let v=Number($('#iterations')?.value??research.maxIterations);if(!Number.isInteger(v)||v<0||v>40)throw Error('Välj ett heltal mellan 0 och 40 iterationer.');research.maxIterations=v;research=normalizeResearch(research);dimensionRequest++;project().research=research;save()}
async function runDimensions(){try{captureResearch();const rev=revision,id=currentId,request=++dimensionRequest;$('#dimension-result').innerHTML='<div class="loading"><span class="spinner"></span>Beräknar masker, dimensionsgrenar och Grover…</div>';const result=await calculate('dimensions',{project:project(),research});if(rev!==revision||id!==currentId||request!==dimensionRequest)return;dimRun=result;quantum=null;if(view==='logic')render();toast('Dimensionskörningen är klar.')}catch(e){toast(e.message);if($('#dimension-result'))$('#dimension-result').innerHTML=`<div class="empty-state error"><p>${esc(e.message)}</p></div>`}}
document.addEventListener('click',async event=>{const el=event.target.closest('button,a[data-action]');const vector=event.target.closest('[data-vector]');if(vector&&model){openVector(vector.dataset.vector);return}if(!el)return;
 try {
 if(el.dataset.step){const next=Number(el.dataset.step);if(next>step&&step===1&&!$('#guide-system-form')?.reportValidity())return;step=next;await go('guide');return}
 if(el.dataset.chooseRoute){selectedRoute=el.dataset.chooseRoute;render();return}
 if(el.dataset.followRoute){selectedRoute=el.dataset.followRoute;step=3;await go('guide');return}
 if(el.dataset.view){await go(el.dataset.view);return}
 if(el.dataset.route){openRoute(el.dataset.route);return}
 if(el.dataset.scenario){commitDraft();const p=starter(el.dataset.scenario);currentId=uid();cases.push({id:currentId,project:p});research=normalizeResearch(p.research||{});selectedRoute=EXAMPLES[el.dataset.scenario]?.focus||'';step=1;closeModal();view='guide';await analyzeCurrent();window.scrollTo(0,0);toast(EXAMPLES[el.dataset.scenario]?'Exemplet är laddat genom hela undersökningen.':'Din nya undersökning är klar att beskriva.');return}
 if(el.dataset.condition){const key=el.dataset.condition;draft.input.flags[key]=el.dataset.value==='?'?null:el.dataset.value==='1';el.parentNode.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el?'true':'false')});$('#save-status').textContent='Ändringar väntar på analys';return}
 if(el.dataset.lens){const lens=el.dataset.lens,p=draft;p.excludedLenses=p.excludedLenses.includes(lens)?p.excludedLenses.filter(x=>x!==lens):[...p.excludedLenses,lens];el.classList.toggle('active',!p.excludedLenses.includes(lens));el.setAttribute('aria-pressed',String(!p.excludedLenses.includes(lens)));el.textContent=(p.excludedLenses.includes(lens)?'○ ':'✓ ')+lens;return}
 if(el.dataset.removeControl!==undefined){captureResearch();const [c]=research.controls.splice(Number(el.dataset.removeControl),1);research.dimensions=research.dimensions.filter(d=>d.key!==c.key);research.walk=research.walk.filter(w=>w.key!==c.key);dimRun=null;quantum=null;project().research=research;save();render();return}
 if(el.dataset.removeWalk!==undefined){captureResearch();research.walk.splice(Number(el.dataset.removeWalk),1);dimRun=null;quantum=null;project().research=research;save();render();return}
 const action=el.dataset.action;if(!action)return;event.preventDefault();if(draft&&['export','report','analyze'].includes(action)){commitDraft();await analyzeCurrent();}
 if(action==='enter')enter();else if(action==='intro')intro();else if(action==='replay')scene.replay();else if(action==='motion'){motionPaused=!motionPaused;scene.pause(motionPaused);el.textContent=motionPaused?'▷':'Ⅱ';el.setAttribute('aria-label',motionPaused?'Starta animation':'Pausa animation');el.setAttribute('aria-pressed',String(motionPaused))}
 else if(action==='new')await go('examples');else if(action==='close')closeModal();else if(action==='analyze')await analyzeCurrent(true);
 else if(action==='export'){download('QCDS-Security-Lab-Work-project.json',project());toast('Projektet exporterat med villkor, belägg och åtgärder.')}
 else if(action==='import')$('#import-file').click();
 else if(action==='report'){if(!model||busy)return;showModal(`<div class="modal-head"><h2>Rapport</h2><button class="icon-btn" data-action="close" aria-label="Stäng">×</button></div><p class="modal-help">Rapporten bygger på aktuell analys. Välj Spara som PDF i utskriftsdialogen.</p><div class="form-actions" style="margin:0 0 20px"><button class="primary" data-action="print">Skriv ut / spara PDF ↗</button></div>${reportMarkup(model,project(),dimRun)}`)}
 else if(action==='print'){$('#print-report').innerHTML=reportMarkup(model,project(),dimRun);window.print()}
 else if(action==='route-evidence'){closeModal();step=5;go('guide')}
 else if(action==='guide-logic'){const r=model.routes.find(x=>x.id===selectedRoute);research.focus=r?.attackVectors?.[0]?.id||research.focus;dimRun=null;quantum=null;await go('logic')}
 else if(action==='focus-vector'){research.focus=selectedVector;dimRun=null;quantum=null;closeModal();go('logic')}
 else if(action==='add-walk'){captureResearch();research.walk.push({key:$('#walk-key').value,value:$('#walk-value').value});project().research=research;dimRun=null;quantum=null;save();render()}
 else if(action==='add-control'){captureResearch();const label=$('#control-label').value.trim(),test=$('#control-test').value.trim();if(!label||!test)throw Error('Beskriv både skyddet och testet.');if(research.controls.length>=32)throw Error('Högst 32 egna kontrollorakel per undersökning.');const key='x_'+uid().replaceAll('-','');research.dimensions.push({key,label,value:$('#control-value').value});research.controls.push({id:'control_'+uid(),key,vectorId:research.focus,label,test});project().research=normalizeResearch(research);dimRun=null;quantum=null;save();render();toast('Kontrolloraklet är tillagt. Kör inferens för att pröva det.')}
 else if(action==='unknown-demo'){captureResearch();const v=model.attackVectorSpace.vectors.find(v=>v.id===research.focus);research.walk=(v?.requires||['external_input','untrusted_content']).slice(0,4).map(key=>({key,value:'?'}));project().research=research;dimRun=null;quantum=null;save();render();toast('Oraklets förutsättningar är nu uttryckligen okända i scenariot.');await runDimensions()}
 else if(action==='run-dimensions')await runDimensions();
 else if(action==='quantum'){if(!dimRun)return;el.disabled=true;el.textContent='Simulerar kretsar…';const rev=revision,run=dimRun;const q=await calculate('quantum',{run});if(rev!==revision||run!==dimRun)return;quantum=q;if(view==='logic')render();toast('Kretsarna är jämförda mot den klassiska referensen.')}
 else if(action==='export-run'&&dimRun)download('QCDS-Work-dimension-run.json',dimRun);else if(action==='export-quantum'&&quantum)download('QCDS-Work-quantum-comparison.json',quantum);
 }catch(e){toast(e.message);el.disabled=false;}
});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=new FormData(form);if(form.id==='guide-system-form'){commitDraft();step=2;view='guide';await analyzeCurrent();}else if(form.id==='system-form'){commitDraft();project().input.name=String(values.get('name')).trim();project().input.description=String(values.get('description')).trim();project().input.attackerGoal=String(values.get('attackerGoal')).trim();project().input.assets=String(values.get('assets')).split(',').map(x=>x.trim()).filter(Boolean).slice(0,100);save();step=2;view='guide';await analyzeCurrent(true)}else if(form.id==='evidence-form'){const source=String(values.get('source')).trim(),observation=String(values.get('observation')).trim();if(!source||!observation)return toast('Ange både källa och observation.');project().evidence.push({id:uid(),findingId:selectedRoute,source,observation,outcome:String(values.get('outcome')),fingerprint:model.fingerprint,createdAt:new Date().toISOString()});await analyzeCurrent();toast('Belägget är sparat och bundet till aktuellt scope.')}else if(form.id==='dimension-evidence'){if(!dimRun)return;research.records.push({vectorId:dimRun.focus.id,bindingKey:dimRun.bindingKey,source:String(values.get('source')).trim(),observation:String(values.get('observation')).trim(),outcome:String(values.get('outcome')),createdAt:new Date().toISOString()});project().research=research;save();await runDimensions();toast('Observationen är bunden till den exakta körningen.')}else if(form.id==='action-form'){project().actions[selectedRoute]={owner:String(values.get('owner')).trim(),note:String(values.get('note')).trim(),status:String(values.get('status')),fingerprint:model.fingerprint};save();toast('Åtgärden är sparad.')}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='case-select'){commitDraft();currentId=el.value;model=null;selectedRoute=exampleFor(project())?.focus||'';step=1;view='guide';research=normalizeResearch(project().research||{});save();await analyzeCurrent()}else if(el.id==='evidence-route'){selectedRoute=el.value;render()}else if(el.id==='route-lens'){routeLens=el.value;$('#route-results').innerHTML=routeRows(model.routes.filter(r=>(!routeLens||r.hitLenses.includes(routeLens))&&(!routeQuery||(JSON.stringify(r)+routeName(r)).toLowerCase().includes(routeQuery.toLowerCase()))))}else if(['focus-vector','run-mode','iterations'].includes(el.id)){try{captureResearch();dimRun=null;quantum=null;$('#dimension-result').innerHTML='<div class="empty-state" style="margin-top:20px"><p>Inställningarna har ändrats. Kör inferens för ett aktuellt resultat.</p></div>'}catch(error){toast(error.message)}}else if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>3e6)throw Error('Projektfilen är för stor (max 3 MB).');const p=validateProject(JSON.parse(await file.text()));commitDraft();currentId=uid();cases.push({id:currentId,project:p});research=normalizeResearch(p.research||{});selectedRoute=exampleFor(p)?.focus||'';step=1;view='guide';await analyzeCurrent();toast('Projektet har importerats som en separat undersökning.')}catch(error){toast('Import misslyckades: '+error.message)}finally{el.value=''}}});
document.addEventListener('input',e=>{if(draft&&e.target.closest('#system-form, #guide-system-form')&&e.target.name){$('#save-status').textContent='Ändringar väntar på analys';const k=e.target.name;draft.input[k]=k==='assets'?e.target.value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,100):e.target.value;}if(e.target.id==='route-search'){routeQuery=e.target.value;$('#route-results').innerHTML=routeRows(model.routes.filter(r=>(!routeLens||r.hitLenses.includes(routeLens))&&(!routeQuery||(JSON.stringify(r)+routeName(r)).toLowerCase().includes(routeQuery.toLowerCase()))))}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('visibilitychange',()=>scene.pause(document.hidden||$('#intro').hidden||motionPaused));
window.addEventListener('hashchange',()=>location.hash==='#work'?enter():intro());
if(location.hash==='#work')enter();else scene.replay();
analyzeCurrent();
